<script setup lang="ts">
import {onMounted,ref} from "vue";
import {useI18n} from "vue-i18n";
import {ManagementTable,ManagedDialog,FloatingError,setErrorFeedback,InfoHint} from "@appnexus/ui";
import type {ProductApi} from "./product";
/** 申请提交到已有审批服务；办理和撤回在现有流程工作台，不重复实现审批引擎。 */
const props=defineProps<{id:string;version:number;readonly:boolean;canSubmit:boolean;readonlyView?:boolean;api:ProductApi;errorText:(e:unknown)=>string}>();const emit=defineEmits<{changed:[]}>();const {t,locale}=useI18n();const rows=ref<Array<Record<string,any>>>([]),organizations=ref<Array<{id:string;name:string}>>([]),organization=ref(""),open=ref(false),busy=ref(false),error=ref(""),key=ref("");
async function load(){try{rows.value=await props.api.approvals(props.id);}catch(e){await setErrorFeedback(error,props.errorText(e));}}
async function prepare(){try{organizations.value=await props.api.approvalOrganizations();organization.value="";key.value=crypto.randomUUID();open.value=true;}catch(e){await setErrorFeedback(error,props.errorText(e));}}
/** 网络不确定时保留原请求键，由用户显式重试，不自动重发审批申请。 */
async function submit(){if(!organization.value||busy.value)return;busy.value=true;try{await props.api.submitApproval(props.id,props.version,organization.value,key.value);open.value=false;emit('changed');}catch(e){await setErrorFeedback(error,props.errorText(e));}finally{busy.value=false;}}
function time(value:string){const date=new Date(value);return Number.isNaN(date.getTime())?'—':new Intl.DateTimeFormat(locale.value,{dateStyle:'medium',timeStyle:'medium'}).format(date);}
onMounted(load);
</script>
<template><section><h3>{{t('productApproval.title')}} <InfoHint v-if="!readonlyView" :content="t('productApproval.hint')"/></h3><FloatingError :title="error"/><ManagementTable :title="t('productApproval.title')" :rows="rows" :columns="[{key:'state',label:t('masterData.status'),width:130},{key:'productVersion',prop:'productVersion',label:t('productV1.version'),width:100},{key:'time',label:t('recordAudit.createdAt'),minWidth:180}]" :loading="busy" :readonly-view="readonlyView" @refresh="load"><template #actions><el-button v-if="canSubmit&&!readonly" v-operation="'ProductApproval.submit'" type="primary" :disabled="busy||rows.some(r=>r.state==='SUBMITTED')" @click="prepare">{{t('productApproval.submit')}}</el-button></template><template #state="{row}"><el-tag class="app-status-tag" :type="row.state==='SUBMITTED'?'warning':'info'">{{t('productApproval.'+row.state)}}</el-tag></template><template #time="{row}">{{time(row.createdAt)}}</template></ManagementTable><ManagedDialog v-model="open" :title="t('productApproval.submit')" :busy="busy"><p>{{t('productApproval.hint')}}</p><el-form label-position="top" class="business-border-label-form"><el-form-item :label="t('productApproval.organization')" required><el-select v-model="organization"><el-option v-for="o in organizations" :key="o.id" :value="o.id" :label="o.name"/></el-select></el-form-item></el-form><template #footer><el-button v-operation="'ProductApproval.submit'" type="primary" :loading="busy" :disabled="!organization" @click="submit">{{t('productApproval.submit')}}</el-button></template></ManagedDialog></section></template>
